+function imageSource(imageUrl: string) {
+  if (!imageUrl || imageUrl.startsWith("blob:") || imageUrl.startsWith("data:")) {
+    return imageUrl;
+  }
+  return `/api/image?url=${encodeURIComponent(imageUrl)}`;
