  border-radius: 26px;
  background: var(--panel);
  box-shadow: 0 30px 80px rgb(44 67 74 / 8%);
  overflow: hidden;
}

.control-panel {
  padding: 42px;
  border-right: 1px solid var(--line);
}

.step-heading {
  margin-bottom: 28px;
  display: flex;
  gap: 17px;
  align-items: flex-start;
}

.step-heading > span {
  width: 33px;
  height: 33px;
  border-radius: 50%;
  background: #e9f5fa;
  color: var(--blue-dark);
