.status-message {
  margin-top: 15px;
  padding: 11px 12px;
  border-radius: 9px;
  background: #f5f7f5;
  color: var(--muted);
  display: flex;
  gap: 9px;
  font-size: 12px;
  line-height: 1.45;
}

.status-message.error {
  background: #fff2ef;
  color: #90483d;
}

.status-message.success {
  background: #eff7ec;
  color: #496a40;
}

.status-dot {
  width: 7px;
  height: 7px;
  margin-top: 5px;
  border-radius: 50%;
  background: currentColor;
  flex: 0 0 auto;
}

.divider {
  height: 1px;
  margin: 31px 0 9px;
  background: var(--line);
}

.editor-toggle {
  width: 100%;
  padding: 17px 0;
  border: 0;
  background: transparent;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  font-size: 15px;
  font-weight: 700;
}

.editor-toggle b {
  margin-right: 12px;
  color: var(--blue-dark);
  font-size: 11px;
}

.editor-note {
  margin: 0 0 20px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.5;
}

.field-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.upload-button {
  min-height: 44px;
  padding: 0 15px;
  border: 1px dashed #aebcbe;
  border-radius: 10px;
  cursor: pointer;
  color: #46565b;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  font-weight: 700;
}

.upload-button input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
}

.preview-panel {
  min-width: 0;
  padding: 42px;
  background: #f2f4f1;
}

.preview-heading {
  margin-bottom: 23px;
  display: flex;
  align-items: end;
  justify-content: space-between;
}

.placement-label {
  margin-bottom: 7px;
  color: var(--blue-dark);
  display: block;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.13em;
}

.dimensions {
  color: var(--muted);
  font-size: 12px;
}

.creative-viewport {
  width: 100%;
  aspect-ratio: 1;
  position: relative;
  overflow: hidden;
  box-shadow: 0 24px 55px rgb(31 52 59 / 15%);
}

.creative-scaler {
  position: absolute;
  top: 0;
  left: 0;
