  background: #bce1f0;
}

.orb-green {
  width: 640px;
  height: 640px;
  right: -255px;
  bottom: -310px;
  background: var(--green);
}

.creative-brand {
  position: absolute;
  top: 64px;
  left: 76px;
  font-size: 34px;
