  align-items: center;
  justify-content: space-between;
  gap: 24px;
  font-size: 23px;
  font-weight: 750;
}

.creative-product {
  width: 390px;
  position: absolute;
  top: 162px;
  right: 88px;
}

.creative-product-image {
  width: 390px;
  height: 704px;
  border-radius: 30px;
  overflow: hidden;
  background: #edf1f1;
