}

.creative-product-image img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}

.image-placeholder {
  width: 100%;
  height: 100%;
  padding: 40px;
  color: #849296;
  display: grid;
  place-items: center;
  text-align: center;
  font-size: 18px;
}

.creative-detail {
  width: 328px;
  min-height: 78px;
  margin: 28px auto 0;
  padding: 18px 27px;
  border-radius: 24px;
  background: rgb(255 255 255 / 90%);
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.creative-detail b {
  color: #5d7884;
  font-size: 14px;
  letter-spacing: 1.1px;
}

.creative-detail span {
  overflow: hidden;
  font-size: 17px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.creative-format {
  position: absolute;
  right: 77px;
  bottom: 42px;
  color: #65767b;
  font-size: 13px;
}

.preview-actions {
  margin-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}

.draft-note {
  display: flex;
  align-items: center;
  gap: 12px;
}

.draft-note > span {
  padding: 6px 8px;
  border: 1px solid #bcc7c7;
