  color: #56666b;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.draft-note p {
  max-width: 285px;
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.4;
}

.download-button {
  min-width: 164px;
  height: 47px;
  padding: 0 18px;
  border: 1px solid #b9c5c5;
  border-radius: 11px;
  background: white;
  gap: 11px;
  font-size: 13px;
}

footer {
  width: min(1440px, calc(100% - 64px));
  min-height: 90px;
  margin: 0 auto;
  border-top: 1px solid var(--line);
  color: var(--muted);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  font-size: 12px;
}

@media (max-width: 1040px) {
  .studio-grid {
    grid-template-columns: 1fr;
  }

  .control-panel {
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }
}

@media (max-width: 680px) {
  .site-header,
  .studio-grid,
  footer {
    width: min(100% - 28px, 1440px);
  }

  .site-header {
    min-height: 68px;
    grid-template-columns: 1fr auto;
  }

  .surface-tabs {
    display: none;
  }

  .prototype-label {
    font-size: 9px;
  }

  .hero {
    width: min(100% - 32px, 980px);
    margin: 55px auto 45px;
  }

  .hero h1 {
    font-size: 44px;
  }

  .hero-copy {
    font-size: 16px;
  }

  .studio-grid {
    border-radius: 18px;
  }

  .control-panel,
  .preview-panel {
    padding: 25px 20px;
  }

  .preview-actions,
  footer {
    align-items: stretch;
    flex-direction: column;
  }

  .download-button {
    width: 100%;
  }

  footer {
    padding: 25px 0;
  }
}

