59:### Part B — Ad quality scorer
61:A second surface that takes an ad creative and scores it before it goes live.
63:It must evaluate against three distinct dimensions:
65:- **Policy and claims.** Is anything here unsubstantiated, non-compliant, or legally risky for a skincare product in this market?
71:- The scorer must work on any ad you feed it, not just ones your generator produced. Include a way to paste in an arbitrary ad. We will test it with ads you have not seen.
73:- Be explicit about where the standard comes from. You are deriving Minimalist's brand rules yourself; the scorer's judgments are only as good as the rules behind them.
75:The two parts should connect. How they connect is your decision. Does the generator self-score before showing output? Does a failing score block export? Does the marketer see the score at all, or only the passing creative? There are defensible answers in several directions — pick one and be ready to explain it.
94:Also include the prompts your app itself uses. If the scorer's judgment lives in a prompt, that prompt is the substance of your work.
106:The top three ways this tool causes a problem in production — not bugs, but ways a well-functioning version of it still leads to a bad outcome. For each, what you'd do about it and whether you'd do it before launch or after.
114:3. **Quality of the standard, not the output.** Any current model will produce a nice-looking ad. The interesting question is whether your scorer encodes a real, defensible view of what good means for this brand, or whether it's asking a model to have opinions and reporting them back unexamined.
export const REVIEW_STATUSES = [
  "pass",
  "revise",
  "evidence_required",
  "human_review",
  "block",
] as const;

export type ReviewStatus = (typeof REVIEW_STATUSES)[number];
export type ReviewDimension = "policy" | "tone" | "language";
export type Severity = "low" | "medium" | "high" | "critical";
export type Confidence = "low" | "medium" | "high";

export type ProductContext = {
  title?: string;
  url?: string;
  description?: string;
};

export type ReviewInput = {
  source: "upload" | "generator";
  imageDataUrl?: string;
  postCopy?: string;
  knownText?: string;
  productContext?: ProductContext;
};

export type ReviewFinding = {
  id: string;
  ruleId: string;
  ruleName: string;
  dimension: ReviewDimension;
  status: Exclude<ReviewStatus, "pass">;
  severity: Severity;
  location: string;
  observed: string;
  inference: string | null;
  whatIsOff: string;
  whyItMatters: string;
  howToFix: string;
  suggestedReplacement: string | null;
  doneWhen: string;
  confidence: Confidence;
  missingInput: string | null;
  sourceBasis: string;
};

export type ReviewVerdict =
  | "ready_for_reviewer_approval"
  | "revise"
  | "evidence_required"
  | "human_review"
  | "do_not_publish";

export type ReviewResult = {
  verdict: ReviewVerdict;
  summary: string;
  dimensions: Record<ReviewDimension, ReviewStatus>;
  extractedText: string;
  visualObservations: string[];
  findings: ReviewFinding[];
  revisedCopy: string | null;
  resubmissionChecklist: string[];
  engine: "gemini+rules" | "rules-only";
  limitations: string[];
};

  return findings.filter((finding) => {
    const key = `${finding.ruleId}:${finding.observed.trim().toLowerCase()}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function strongestStatus(statuses: ReviewStatus[]): ReviewStatus {
  return statuses.reduce<ReviewStatus>((strongest, status) =>
    STATUS_ORDER[status] > STATUS_ORDER[strongest] ? status : strongest, "pass");
}

function verdictFor(status: ReviewStatus): ReviewVerdict {
  if (status === "block") return "do_not_publish";
  if (status === "human_review") return "human_review";
  if (status === "evidence_required") return "evidence_required";
  if (status === "revise") return "revise";
  return "ready_for_reviewer_approval";
}

const VERDICT_SUMMARIES: Record<ReviewVerdict, string> = {
  do_not_publish: "Do not publish yet. Resolve the critical finding first.",
  human_review: "A specialist decision or missing visual review is required before publication.",
  evidence_required: "The creative needs claim evidence or an approved claim match before publication.",
  revise: "Revise the flagged copy or execution, then score the updated creative again.",
  ready_for_reviewer_approval: "No issue was detected by this prototype. It is ready for final reviewer approval—not automatically approved.",
};

export function assembleReview(
  input: ReviewInput,
  model: ModelReview | null,
  modelError?: string,
): ReviewResult {
  const local = analyzeText(input);
  const vision = model ? normalizeModelFindings(model) : [];
  const limitations: string[] = [];
  let findings = dedupeFindings([...local, ...vision]);

  if (!model && input.imageDataUrl) {
    findings.push({
      id: "input-visual-review",
      ruleId: "INPUT",
      ruleName: "Visual review unavailable",
      dimension: "policy",
      status: "human_review",
      severity: "high",
      location: "Uploaded creative",
      observed: "The image was received, but no vision model was available to read it.",
      inference: null,
      whatIsOff: "Visual copy, disclaimer legibility, layout, and asset integrity have not been assessed.",
      whyItMatters: "A text-only check cannot safely clear an image ad.",
      howToFix: "Configure GEMINI_API_KEY and rescore, or paste all visible copy and complete a manual visual review.",
      suggestedReplacement: null,
      doneWhen: "The image has been read by the vision scorer or signed off by a human reviewer.",
      confidence: "high",
      missingInput: "Vision analysis",
      sourceBasis: "Scorer input-quality safeguard",
    });
    limitations.push(modelError ?? "Gemini vision is not configured; only supplied text was checked.");
  }

  if (!input.imageDataUrl) {
    limitations.push("No ad image was supplied; visual hierarchy, disclaimer legibility, and asset integrity were not assessed.");
  }

  const dimensions = (["policy", "tone", "language"] as ReviewDimension[]).reduce(
    (result, dimension) => {
      result[dimension] = strongestStatus(findings.filter((finding) => finding.dimension === dimension).map((finding) => finding.status));
      return result;
    },
    { policy: "pass", tone: "pass", language: "pass" } as Record<ReviewDimension, ReviewStatus>,
  );
  const overallStatus = strongestStatus(Object.values(dimensions));
  const verdict = verdictFor(overallStatus);
  const checklist = model?.resubmissionChecklist ?? [];
  const actionableChecklist = findings.slice(0, 5).map((finding) => finding.doneWhen);

  return {
    verdict,
    summary: VERDICT_SUMMARIES[verdict],
    dimensions,
    extractedText: model?.extractedText || [input.knownText, input.postCopy].filter(Boolean).join("\n"),
    visualObservations: model?.visualObservations ?? [],
    findings,
    revisedCopy: model?.revisedCopy ?? null,
    resubmissionChecklist: [...new Set([...actionableChecklist, ...checklist])].slice(0, 7),
    engine: model ? "gemini+rules" : "rules-only",
    limitations,
  };
}

      <section className="review-output-panel" aria-live="polite" aria-label="Scorer output">
        {!result && !isReviewing ? <ReviewEmptyState /> : null}
        {isReviewing ? <ReviewLoading /> : null}
        {result && !isReviewing ? <ReviewOutput result={result} /> : null}
      </section>
    </section>
  );
}

function ReviewOutput({ result }: { result: ReviewResult }) {
  return (
    <div className="review-results">
      <section className={`verdict-card status-${statusFromVerdict(result.verdict)}`}>
        <p>Overall decision</p>
        <h2>{VERDICT_LABELS[result.verdict]}</h2>
        <span>{result.summary}</span>
      </section>

      <div className="dimension-grid">
        {Object.entries(result.dimensions).map(([dimension, status]) => (
          <div className={`dimension-card status-${status}`} key={dimension}>
            <span>{dimension === "policy" ? "Policy & claims" : `Brand ${dimension}`}</span>
            <strong>{STATUS_LABELS[status]}</strong>
          </div>
        ))}
      </div>

      {result.findings.length ? (
        <section className="findings-section">
          <div className="result-heading">
            <div>
              <p>Fix first</p>
              <h3>{result.findings.length} actionable {result.findings.length === 1 ? "finding" : "findings"}</h3>
            </div>
            <span>{result.engine === "gemini+rules" ? "Vision + rules" : "Rules only"}</span>
          </div>
          <div className="finding-list">
            {result.findings.map((finding, index) => (
              <article className="finding-card" key={finding.id}>
                <header>
                  <div><span>{index + 1}</span><b>{finding.ruleId} · {finding.ruleName}</b></div>
                  <em className={`finding-status status-${finding.status}`}>{STATUS_LABELS[finding.status]}</em>
                </header>
                <dl>
                  <div><dt>Where</dt><dd>{finding.location}</dd></div>
                  <div><dt>Observed</dt><dd>“{finding.observed}”</dd></div>
                  {finding.inference ? <div><dt>Inference</dt><dd>{finding.inference}</dd></div> : null}
                  <div><dt>What’s off</dt><dd>{finding.whatIsOff}</dd></div>
                  <div><dt>Why it matters</dt><dd>{finding.whyItMatters}</dd></div>
                  <div className="fix-row"><dt>How to fix</dt><dd>{finding.howToFix}</dd></div>
                  {finding.suggestedReplacement ? <div className="replacement-row"><dt>Try</dt><dd>“{finding.suggestedReplacement}”</dd></div> : null}
                  <div><dt>Done when</dt><dd>{finding.doneWhen}</dd></div>
                </dl>
                <div className="finding-meta">
                  <span>{finding.severity} severity · {finding.confidence} confidence</span>
                  {finding.missingInput ? <span>Needs: {finding.missingInput}</span> : null}
                  <span>Basis: {finding.sourceBasis}</span>
                </div>
              </article>
            ))}
          </div>
        </section>
      ) : (
        <section className="no-findings">
          <b>No rule violation was detected.</b>
          <p>This is a first-pass screen, not final legal or claims approval.</p>
        </section>
      )}

      {result.revisedCopy ? (
        <section className="revised-copy">
          <p>Suggested revision</p>
          <blockquote>{result.revisedCopy}</blockquote>
        </section>
      ) : null}

      {result.resubmissionChecklist.length ? (
        <section className="checklist-card">
          <h3>Ready to rescore when…</h3>
          <ul>{result.resubmissionChecklist.map((item) => <li key={item}>{item}</li>)}</ul>
        </section>
      ) : null}

      {result.limitations.length ? (
        <details className="limitations">
          <summary>Scorer limitations</summary>
          <ul>{result.limitations.map((item) => <li key={item}>{item}</li>)}</ul>
        </details>
      ) : null}
    </div>
  );
}

function ReviewEmptyState() {
  return (
    <div className="review-empty">
      <span>02</span>
      <h2>Your scorer output will appear here.</h2>
      <p>It will identify the exact copy or visual area, explain the issue, and give a concrete fix and completion check.</p>
      <div><b>Policy & claims</b><b>Brand tone</b><b>Brand language</b></div>
    </div>
  );
}

function ReviewLoading() {
  return (
    <div className="review-loading">
      <span />
      <h2>Scoring the creative…</h2>
      <p>Checking visible copy, claims, tone, language, hierarchy and qualifications.</p>
    </div>
  );
}

function statusFromVerdict(verdict: ReviewResult["verdict"]): ReviewStatus {
  if (verdict === "do_not_publish") return "block";
  if (verdict === "ready_for_reviewer_approval") return "pass";
  return verdict;
}

async function prepareImageForReview(file: File) {
  if (!/^image\/(png|jpeg|webp)$/.test(file.type)) throw new Error("Use a PNG, JPEG, or WebP image.");
  if (file.size > 15 * 1024 * 1024) throw new Error("Use an image smaller than 15 MB.");

  const original = await readFileAsDataUrl(file);
  const image = await loadImage(original);
  const maxDimension = 1600;
  const scale = Math.min(1, maxDimension / Math.max(image.naturalWidth, image.naturalHeight));
  const canvas = document.createElement("canvas");
  canvas.width = Math.max(1, Math.round(image.naturalWidth * scale));

