.checklist-card h3 {
  margin: 0;
  font-size: 20px;
  letter-spacing: -0.025em;
}

.result-heading > span {
  color: var(--muted);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.finding-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.finding-card {
  border: 1px solid #d4dcda;
  border-radius: 14px;
  background: white;
  overflow: hidden;
}

.finding-card > header {
  padding: 17px 19px;
  border-bottom: 1px solid #e0e5e3;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}

.finding-card > header > div {
  display: flex;
  align-items: center;
  gap: 10px;
}

.finding-card > header div > span {
  width: 25px;
  height: 25px;
  border-radius: 50%;
  background: #eef3f1;
  display: grid;
  place-items: center;
  font-size: 10px;
  font-weight: 800;
}

.finding-card header b {
  font-size: 13px;
}

.finding-status {
  padding: 6px 8px;
  border-radius: 6px;
  background: #f1f3f2;
  color: #4f6065;
  font-size: 9px;
  font-style: normal;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  white-space: nowrap;
}

.finding-status.status-block { background: #feeae6; color: #9e382f; }
.finding-status.status-human_review { background: #f5eafb; color: #764282; }
.finding-status.status-evidence_required { background: #fff2d6; color: #8c5e09; }
.finding-status.status-revise { background: #fff5db; color: #8e620d; }

.finding-card dl {
  margin: 0;
  padding: 8px 19px;
}

.finding-card dl > div {
  padding: 11px 0;
  border-bottom: 1px solid #edf0ef;
  display: grid;
  grid-template-columns: 105px 1fr;
  gap: 14px;
}

.finding-card dl > div:last-child {
  border-bottom: 0;
}

.finding-card dt {
  color: #788589;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.finding-card dd {
  margin: 0;
  color: #334348;
  font-size: 12px;
  line-height: 1.5;
}

.finding-card .fix-row dd {
  color: #152629;
  font-weight: 700;
}

.finding-card .replacement-row {
  margin: 2px -8px;
  padding: 13px 8px;
  border: 0;
  border-radius: 8px;
  background: #edf7fb;
}

.finding-meta {
  padding: 13px 19px;
  border-top: 1px solid #e0e5e3;
  background: #f8faf9;
  color: #718085;
  display: flex;
  flex-wrap: wrap;
  gap: 8px 18px;
  font-size: 9px;
  line-height: 1.45;
}

.revised-copy,
.checklist-card,
.no-findings {
  padding: 22px 24px;
  border: 1px solid #d6dedd;
  border-radius: 14px;
  background: white;
}

.revised-copy blockquote {
  margin: 0;
  color: #26383d;
  font-size: 14px;
  line-height: 1.6;
  white-space: pre-wrap;
}

.checklist-card ul,
.limitations ul {
  margin: 14px 0 0;
  padding-left: 19px;
  color: #43555a;
  font-size: 12px;
  line-height: 1.55;
}

.checklist-card li + li,
.limitations li + li {
  margin-top: 8px;
}

.no-findings b {
  color: #3d7653;
  font-size: 15px;
}

.no-findings p {
  margin: 8px 0 0;
  color: var(--muted);
  font-size: 12px;
}

.limitations {
  color: var(--muted);
  font-size: 11px;
}

.limitations summary {
  cursor: pointer;
  font-weight: 700;
}

footer {
  width: min(1440px, calc(100% - 64px));
  min-height: 90px;
  margin: 0 auto;
  border-top: 1px solid var(--line);

